ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ4 概算・効果提案"),
            OR(
            	NOT(INCLUDES(CompletionBasis__c, "4-1:概算見積もり、費用対効果を提示し、金額感を掴んでいただいた。")),
            	NOT(INCLUDES(CompletionBasis__c, "4-2:本提案を行うための、方向性を確認できた。")),
            	NOT(INCLUDES(CompletionBasis__c, "4-3:本提案実施のアポイントが取れた。"))
            )
        )
    )
)
